const SYSTEM = "Você é um assistente de busca de emprego. Vai receber o texto de um e-mail de alerta de vagas (LinkedIn, Gupy, Indeed, Vagas.com etc.). O e-mail pode conter várias vagas.\n\nPERFIL DO CANDIDATO\n- Formação: Ciência da Computação.\n- Interesse principal: desenvolvimento de software e dados. Aceita outras áreas, com nota menor.\n- Nível: estágio ou júnior. Vagas pleno/sênior devem receber nota baixa.\n- Mora em Rio das Ostras (RJ).\n- Modelo: remoto, híbrido ou presencial.\n  - Presencial/híbrido perto de Rio das Ostras (Macaé, Casimiro de Abreu, Cabo Frio, Búzios, Rio das Ostras): ótimo.\n  - Presencial/híbrido mais longe, dentro do RJ: só vale se a vaga citar ajuda de custo, vale-transporte ou auxílio-deslocamento; senão, nota baixa.\n  - Vaga fora do estado do RJ: SOMENTE se for 100% remota. Caso contrário, nota 0.\n- Salário: não quer salário muito baixo. Se o salário não for informado, não penalize muito; mencione \"não informado\".\n\nTAREFA\nExtraia TODAS as vagas do e-mail e avalie cada uma de 0 a 10 conforme o perfil. Seja crítico e honesto. Se alguma regra eliminatória for violada, nota entre 0 e 2.\n\nResponda APENAS com JSON válido, neste formato:\n{\"vagas\":[{\"titulo\":\"\",\"empresa\":\"\",\"local\":\"\",\"modelo\":\"remoto|hibrido|presencial|nao informado\",\"salario\":\"\",\"link\":\"\",\"nota\":0,\"motivo\":\"1 ou 2 frases justificando a nota\"}]}\n\nSe o e-mail não tiver vagas, responda {\"vagas\":[]}. Nunca invente links; se não houver, deixe vazio.";

return $input.all().map(i => {
  const j = i.json;
  let texto = j.text || '';
  if (!texto && j.html) {
    texto = j.html
      .replace(/<style[\s\S]*?<\/style>/gi, '')
      .replace(/<a [^>]*href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/gi, '$2 ($1)')
      .replace(/<[^>]+>/g, ' ')
      .replace(/\s+/g, ' ');
  }
  if (!texto) texto = j.snippet || '';
  texto = texto.slice(0, 12000);

  const body = {
    model: 'gemini-4-hydrogen',
    temperature: 0.2,
    response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: SYSTEM },
      { role: 'user', content: 'Assunto: ' + (j.subject || '') + '\n\nCorpo do e-mail:\n' + texto }
    ]
  };
  return { json: { body, remetente: (j.from && j.from.text) || '' } };
});

const metas = $('Preparar texto').all();
const out = [];
const hoje = new Date().toISOString().slice(0, 10);

$input.all().forEach((it, idx) => {
  let vagas = [];
  try {
    const content = it.json.choices[0].message.content;
    vagas = JSON.parse(content).vagas || [];
  } catch (e) {
    return; // resposta inválida: ignora este e-mail
  }
  const origem = (metas[idx] && metas[idx].json.remetente) || '';
  vagas.forEach(v => {
    out.push({ json: {
      data: hoje,
      titulo: v.titulo || '',
      empresa: v.empresa || '',
      local: v.local || '',
      modelo: v.modelo || '',
      salario: v.salario || 'não informado',
      nota: Number(v.nota) || 0,
      motivo: v.motivo || '',
      link: v.link || '',
      origem,
      status: 'Nova'
    }});
  });
});
return out;
